package target

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"sync"

	"github.com/servtuner/servtuner/bench/internal/spec"
)

// sglangCatalogJSON is every SGLang server argument as SGLang's own field
// declarations describe it at the pinned version: help text, type, default,
// choices and aliases. It is generated by tools/sglang-catalog/dump.py
// (`just sglang-catalog`), never edited by hand.
//
//go:embed sglang_catalog.json
var sglangCatalogJSON []byte

// sglangPrefix is the start of every SGLang knob's name.
const sglangPrefix = "sglang."

// sglangCatalogFile is the generated file's shape. Its flags have the vLLM
// catalog's shape; other_flags lists the spellings that are not knobs (list
// and JSON flags, and the flags SGLang registers by hand).
type sglangCatalogFile struct {
	SGLangVersion string            `json:"sglang_version"`
	SGLangCommit  string            `json:"sglang_commit"`
	Flags         []vllmCatalogFlag `json:"flags"`
	OtherFlags    []string          `json:"other_flags"`
}

var readSGLangCatalog = sync.OnceValues(func() (sglangCatalogFile, error) {
	var catalog sglangCatalogFile
	if err := json.Unmarshal(sglangCatalogJSON, &catalog); err != nil {
		return sglangCatalogFile{}, fmt.Errorf("read the embedded SGLang flag catalog: %w", err)
	}
	return catalog, nil
})

// sglangOwnedFields are the SGLang fields the deployer sets itself or that
// would break how servtuner serves and reaches the model, so they are never
// knobs: the model and its name, where and how it listens (host, port, TLS),
// the metrics servtuner needs, and a config file. A field whose name says it
// holds a secret (IsSecretName: api_key, admin_api_key, tokens) is never a
// knob either.
var sglangOwnedFields = map[string]bool{
	"model_path": true, "tokenizer_path": true, "served_model_name": true, "config": true,
	"host": true, "port": true, "ssl_keyfile": true, "ssl_certfile": true, "ssl_ca_certs": true,
	"ssl_keyfile_password": true, "enable_ssl_refresh": true, "enable_metrics": true, "download_dir": true,
}

// sglangKnobLabels label the knobs servtuner knows by name; the rest are named
// from their field (humanizeField).
var sglangKnobLabels = map[string]string{
	KnobSGLangTPSize:                  "Tensor parallel size",
	KnobSGLangDPSize:                  "Data parallel size",
	KnobSGLangPPSize:                  "Pipeline parallel size",
	KnobSGLangMemFractionStatic:       "Static memory fraction",
	KnobSGLangMaxRunningRequests:      "Max running requests",
	KnobSGLangMaxQueuedRequests:       "Max queued requests",
	KnobSGLangMaxTotalTokens:          "Max total tokens (KV pool)",
	KnobSGLangChunkedPrefillSize:      "Chunked prefill size",
	KnobSGLangMaxPrefillTokens:        "Max prefill tokens",
	KnobSGLangSchedulePolicy:          "Schedule policy",
	KnobSGLangScheduleConservativness: "Schedule conservativeness",
	KnobSGLangDisableRadixCache:       "Disable radix cache",
	KnobSGLangContextLength:           "Context length",
	KnobSGLangDtype:                   "Weight data type",
	KnobSGLangKVCacheDtype:            "KV cache data type",
	KnobSGLangQuantization:            "Quantization",
	KnobSGLangAttentionBackend:        "Attention backend",
	KnobSGLangPageSize:                "KV page size",
	KnobSGLangStreamInterval:          "Stream interval",
	KnobSGLangSpecAlgorithm:           "Speculative algorithm",
	KnobSGLangSpecNumSteps:            "Speculative steps",
	KnobSGLangSpecNumDraftTokens:      "Speculative draft tokens",
	KnobSGLangCudaGraphMaxBSDecode:    "Max CUDA graph batch (decode)",
}

// isSGLangCatalogKnob reports whether a catalog flag is a knob: one value,
// not servtuner's to set, and not a secret.
func isSGLangCatalogKnob(flag vllmCatalogFlag) bool {
	_, single := knobKinds[flag.Kind]
	return single && !sglangOwnedFields[flag.Dest] && !IsSecretName(flag.Dest)
}

// IsSGLangKnob reports whether name is an SGLang knob: a flag of SGLang's
// catalog that is one (isSGLangCatalogKnob).
func IsSGLangKnob(name string) bool {
	_, known := sglangKnobsByName()[name]
	return known
}

var sglangKnobsByName = sync.OnceValue(func() map[string]vllmCatalogFlag {
	file, err := readSGLangCatalog()
	if err != nil {
		panic(err) // embedded and tested
	}
	knobs := map[string]vllmCatalogFlag{}
	for _, flag := range file.Flags {
		if isSGLangCatalogKnob(flag) {
			knobs[sglangPrefix+flag.Dest] = flag
		}
	}
	return knobs
})

// SGLangKnobCatalog describes every SGLang knob, labelled when servtuner knows
// it by name (it captures those from a running target) and named from its field
// otherwise, and every other spelling SGLang accepts.
func SGLangKnobCatalog() (spec.KnobCatalog, error) {
	file, err := readSGLangCatalog()
	if err != nil {
		return spec.KnobCatalog{}, err
	}
	knobs := make([]spec.KnobDescription, 0, len(file.Flags))
	other := append([]string{}, file.OtherFlags...)
	for _, flag := range file.Flags {
		name := sglangPrefix + flag.Dest
		if !isSGLangCatalogKnob(flag) {
			other = append(other, flag.Flag)
			other = append(other, flag.Aliases...)
			continue
		}
		label, builtIn := sglangKnobLabels[name]
		if !builtIn {
			label = humanizeField(flag.Dest)
		}
		description := spec.KnobDescription{
			Name: name, Label: label, Flag: flag.Flag, Aliases: flag.Aliases, NegativeFlags: flag.NegativeFlags,
			Group: flag.Group, Kind: flag.Kind, Default: flag.Default, Help: flag.Help, Limits: flag.Limits,
			BuiltIn: builtIn,
		}
		if flag.Choices != nil {
			choices := spec.KnobDescriptionChoices(flag.Choices)
			description.Choices = &choices
		}
		knobs = append(knobs, description)
	}
	sort.Strings(other)
	return spec.KnobCatalog{Server: spec.KnobCatalogServerSglang, Version: file.SGLangVersion, Commit: file.SGLangCommit, Knobs: knobs, OtherFlags: other}, nil
}

// KnobCatalogFor is the knob catalog of a model server: vllm or sglang.
func KnobCatalogFor(server spec.KnobCatalogServer) (spec.KnobCatalog, error) {
	switch server {
	case spec.KnobCatalogServerVllm:
		return KnobCatalog()
	case spec.KnobCatalogServerSglang:
		return SGLangKnobCatalog()
	default:
		return spec.KnobCatalog{}, fmt.Errorf("no knob catalog for server %q (vllm or sglang)", server)
	}
}

// ServerOfKnob is the model server a knob belongs to: vllm, sglang, or "" for neither.
func ServerOfKnob(name string) spec.KnobCatalogServer {
	switch {
	case IsVLLMKnob(name):
		return spec.KnobCatalogServerVllm
	case IsSGLangKnob(name):
		return spec.KnobCatalogServerSglang
	default:
		return ""
	}
}
